package in.rkgitm.hub.security;
import org.springframework.context.annotation.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.web.cors.*;import java.util.List;import org.springframework.security.config.annotation.web.builders.HttpSecurity;import org.springframework.security.config.http.SessionCreationPolicy;import org.springframework.security.web.SecurityFilterChain;import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter;
@Configuration public class SecurityConfig{private final JwtFilter jwt;@Value("${FRONTEND_URL:http://localhost:3000}") String frontendUrl;public SecurityConfig(JwtFilter jwt){this.jwt=jwt;}@Bean SecurityFilterChain filter(HttpSecurity http)throws Exception{return http.csrf(c->c.disable()).cors(c->{}).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.requestMatchers("/api/auth/login","/api/achievements/public").permitAll().requestMatchers(org.springframework.http.HttpMethod.POST,"/api/achievements").permitAll().requestMatchers("/api/achievements/pending","/api/achievements/admin","/api/achievements/*/status").hasAnyRole("FACULTY","ADMIN").requestMatchers("/api/health").permitAll().anyRequest().authenticated()).addFilterBefore(jwt,UsernamePasswordAuthenticationFilter.class).build();} @Bean CorsConfigurationSource corsConfigurationSource(){CorsConfiguration c=new CorsConfiguration();c.setAllowedOrigins(List.of(frontendUrl));c.setAllowedMethods(List.of("GET","POST","PATCH","OPTIONS"));c.setAllowedHeaders(List.of("Authorization","Content-Type"));UrlBasedCorsConfigurationSource src=new UrlBasedCorsConfigurationSource();src.registerCorsConfiguration("/**",c);return src;}}